use crate::{jc053 as b,model::*,unit_support::*,rules::*};
fn settle(g:&mut Game){for _ in 0..80{if g.pending.is_some()||g.stack.is_empty(){return;}crate::jc029_tests::pass_top(g);}panic!()}
fn setup()->(Game,String){let mut g=game();g.players[0].society_zone.card=Some(g.make_card("MSJC01",0));fund(&mut g,0,"JC042",10);let id=attach(&mut g,b::ID,"society:p0");(g,id)}
fn activate(g:&mut Game,id:&str,key:&str){act(g,0,Action{card_id:Some(id.into()),ability_id:Some(key.into()),..Action::new("activate")});}
fn enemy_removed(g:&mut Game){g.regions[0].influence[1]=2;g.place_influence(0,0,1);assert_eq!(g.regions[0].influence[1],1);}
fn bad(g:&Game,x:&Game){assert!(Game::from_persisted(&serde_json::to_string(x).unwrap()).is_err());let mut r=crate::jc029_tests::envelope(g);r.game=x.clone();assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&r).unwrap()).is_err());}
#[test]fn jc053_original_identity_and_canonical_program(){assert_current_serial_catalog();let c=crate::catalog::card(b::ID);assert!(!c.supported);assert!(c.unique);assert_eq!(c.cost,2);assert_eq!(c.loyalty,vec!["红色"]);let d=b::definition();b::validate_definition(b::ID,&d).unwrap();let mut a=d.abilities.iter().find(|a|a.key==b::DRAW).unwrap().clone();a.costs[0]=Cost::Assets(1);assert!(b::validate_ability(b::ID,&a).is_err());assert!(b::validate_ability("JC039",&d.abilities[1]).is_err());crate::rules::validate_definitions(crate::rules::definitions()).unwrap();}
#[test]fn jc053_public_attach_then_optional_draw_and_decline(){for decline in [false,true]{let(mut g,id)=setup();enemy_removed(&mut g);let hand=g.players[0].hand.len();activate(&mut g,&id,b::DRAW);settle(&mut g);assert_eq!(g.pending.as_ref().unwrap().choice.kind,"jc053-draw");restore(&mut g);choose(&mut g,if decline{vec![]}else{vec!["draw".into()]});assert_eq!(g.players[0].hand.len(),hand+usize::from(!decline));assert!(g.attachments.iter().find(|a|a.card.id==id).unwrap().card.exhausted);}}
#[test]fn jc053_no_history_friendly_only_and_no_future_listener(){let(mut g,id)=setup();g.regions[0].influence[0]=2;g.remove_influence_recorded(0,0,1);activate(&mut g,&id,b::DRAW);settle(&mut g);assert!(g.pending.is_none());let hand=g.players[0].hand.len();enemy_removed(&mut g);g.drive().unwrap();assert!(g.pending.is_none());assert_eq!(g.players[0].hand.len(),hand);}
#[test]fn jc053_history_at_resolution_includes_response_and_survives_source_departure(){let(mut g,id)=setup();activate(&mut g,&id,b::DRAW);enemy_removed(&mut g);g.return_hand(&id);restore(&mut g);settle(&mut g);choose(&mut g,vec!["draw".into()]);}
#[test]fn jc053_invalid_choice_duplicate_and_corruption(){let(mut g,id)=setup();enemy_removed(&mut g);activate(&mut g,&id,b::DRAW);settle(&mut g);for n in 0..6{let mut x=g.clone();match n{0=>x.influence_removals[0].amount=0,1=>x.influence_removals[0].turn+=1,2=>x.influence_removals.push(x.influence_removals[0].clone()),3=>x.pending.as_mut().unwrap().choice.min=Some(1),4=>{let ChoiceResolution::Frame{frame:f,..}=&mut x.pending.as_mut().unwrap().resolution else{panic!()};f.already_paid.clear();},_=>{let ChoiceResolution::Frame{frame:f,..}=&x.pending.as_ref().unwrap().resolution else{panic!()};x.effects.push_back(Effect::Frame{frame:f.clone()});}}bad(&g,&x);}let a=Action{choice_id:Some(g.pending.as_ref().unwrap().choice.id.clone()),selected:Some(vec!["draw".into()]),..Action::new("choose")};reject(&mut g,1,a.clone());reject(&mut g,0,Action{amount:Some(2),..a.clone()});act(&mut g,0,a.clone());reject(&mut g,0,a);}
#[test]fn jc053_discount_is_society_scoped_and_not_conceal(){let(mut g,id)=setup();activate(&mut g,&id,b::DISCOUNT);settle(&mut g);let m=g.modifiers.last().unwrap();assert!(matches!(&m.filter,CardFilter::PrintedSociety(s)if s=="鸣钟教派"));assert!(m.paid_reveal);assert_eq!(m.uses,1);assert!(m.filter.matches(crate::catalog::card("JC042")));assert!(!m.filter.matches(crate::catalog::card("JC003")));restore(&mut g);let mut x=g.clone();x.modifiers.last_mut().unwrap().amount=2;bad(&g,&x);}
#[test]fn jc053_zero_removal_and_turn_reset(){let(mut g,_)=setup();g.remove_influence_recorded(0,1,9);assert!(g.influence_removals.is_empty());enemy_removed(&mut g);let turn=g.turn;for _ in 0..400{if g.turn!=turn{break;}if g.pending.is_some(){let p=g.pending.as_ref().unwrap();let ids=p.choice.options.iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect();choose(&mut g,ids);}else{let s=(0..4).find(|s|g.legal_actions(*s).iter().any(|a|a.action.kind=="pass")).unwrap();act(&mut g,s,Action::new("pass"));}}assert!(g.turn>turn);assert!(g.influence_removals.is_empty());}
#[test]fn jc053_both_discount_channels_consume_once(){for reveal in [false,true]{let(mut g,id)=setup();activate(&mut g,&id,b::DISCOUNT);settle(&mut g);let source=if reveal{let c=field(&mut g,"JC042",0);g.board_mut(&c).unwrap().face_down=true;c}else{held(&mut g,"JC042",0)};let before=g.resources(0);act(&mut g,0,Action{card_id:Some(source),region:(!reveal).then_some(0),..Action::new(if reveal{"reveal"}else{"deploy"})});assert_eq!(g.resources(0),before);assert!(g.modifiers.iter().all(|m|m.uses==0));settle(&mut g);restore(&mut g);}}
#[test]fn jc053_conceal_preserves_discount_and_wrong_team_does_not_trigger(){let(mut g,id)=setup();activate(&mut g,&id,b::DISCOUNT);settle(&mut g);let source=held(&mut g,"JC042",0);act(&mut g,0,Action{card_id:Some(source),region:Some(0),..Action::new("conceal")});assert!(g.modifiers.iter().any(|m|m.uses==1));}
use crate::{catalog,abi112_review_play_tests::Trace};
fn duplicate(mut v:serde_json::Value)->serde_json::Value{for s in v["steps"].as_array_mut().unwrap(){let r=crate::room::RoomEnvelope::from_persisted(s["expected"]["state"].as_str().unwrap()).unwrap();let d=r.transition(s["seat"].as_u64().unwrap()as usize,Some(serde_json::from_value(s["command"].clone()).unwrap()),0).unwrap();assert_eq!(d.outcome,"rejected");assert!(!d.changed&&d.journal.is_empty());assert_eq!(d.state,s["expected"]["state"]);s["duplicate"]=serde_json::to_value(d).unwrap();}v}
fn construct(seed:u64)->Game{use crate::deck;let mut d=deck::preset("watchers").unwrap();d.id="jc053-natural".into();d.society_id=Some("MSJC09".into());d.core_card_id=None;d.cards=[(b::ID,1),("JC042",3),("JZ30",3),("JC125",43)].into_iter().map(|(id,count)|catalog::DeckEntry{card_id:id.into(),count}).collect();assert!(deck::validate(d.clone()).is_err());let mut cards=catalog::catalog().cards.clone();cards.iter_mut().find(|c|c.id==b::ID).unwrap().supported=true;let d=deck::validate_with_cards(d,&cards).unwrap();let mut other=deck::preset("watchers").unwrap();other.society_id=None;other.core_card_id=None;other.cards=vec![catalog::DeckEntry{card_id:"JC125".into(),count:50}];let other=deck::validate(other).unwrap();let mut g=Game::new("jc053".into(),"LOCAL".into(),"teams".into(),"P0".into(),"watchers".into(),seed).unwrap();for s in 1..4{g.join(format!("P{s}"),"watchers".into()).unwrap();}g.start_validated_decks(vec![d,other.clone(),other.clone(),other]).unwrap();g.drive().unwrap();g}
fn natural()->serde_json::Value{let seed=(1..10000).find(|seed|{let g=construct(*seed);[b::ID,"JC042","JZ30"].iter().all(|id|g.players[0].hand.iter().any(|c|c.definition==*id))}).expect("legal seed");let g=construct(seed);let deck=g.players[0].deck_snapshot.clone().unwrap();let mut t=Trace::new_preserving_rng(g,"jc053-natural-fifty-attach-discount-deploy".into(),891);let(mut attached,mut discounted,mut deployed)=(false,false,false);for _ in 0..1200{if let Some(p)=t.room.game.pending.clone(){let ids=p.choice.options.iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect();t.choose(ids);continue;}if deployed&&t.room.game.stack.is_empty()&&t.room.game.effects.is_empty(){break;}if !t.room.game.stack.is_empty(){t.pass();continue;}let g=&t.room.game;let legal=g.legal_actions(0);let a=if !attached{legal.iter().find(|a|a.action.kind=="play"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|c.id==*id&&c.definition==b::ID)))}else if !discounted{legal.iter().find(|a|a.action.ability_id.as_deref()==Some(b::DISCOUNT))}else{legal.iter().find(|a|a.action.kind=="deploy"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|c.id==*id&&c.definition=="JC042")))};let a=a.or_else(||(!attached).then(||legal.iter().find(|a|a.action.kind=="asset"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|c.id==*id&&!matches!(c.definition.as_str(),b::ID|"JC042"))))).flatten());if let Some(a)=a{let a=a.action.clone();if a.kind=="play"{attached=true;}if a.ability_id.as_deref()==Some(b::DISCOUNT){discounted=true;}if a.kind=="deploy"{deployed=true;}t.action(0,a);}else{t.pass();}}assert!(attached&&discounted&&deployed,"{seed}: {attached}/{discounted}/{deployed}");let mut v=t.value();v["construction"]=serde_json::json!({"seed":seed,"deck":deck,"ordinaryCards":50,"privateRegistryOnly":true,"noLayoutOrResourceMutation":true});duplicate(v)}
fn prepared()->serde_json::Value{let(mut g,id)=setup();fund(&mut g,0,"WM058",6);let x=field(&mut g,"WM058",0);g.board_mut(&x).unwrap().face_down=true;g.regions[0].influence[1]=2;let mut t=Trace::new_preserving_rng(g,"jc053-real-reveal-removal-draw".into(),892);t.action(0,Action{card_id:Some(x),..Action::new("reveal")});let mut activated=false;for _ in 0..80{if let Some(p)=t.room.game.pending.clone(){let ids=if p.choice.kind=="jc053-draw"{vec!["draw".into()]}else if matches!(p.resolution,ChoiceResolution::Declare{..}){vec!["accept".into()]}else{p.choice.options.iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect()};t.choose(ids);}else if !t.room.game.stack.is_empty(){t.pass();}else if !activated{assert!(!t.room.game.influence_removals.is_empty());activated=true;t.action(0,Action{card_id:Some(id.clone()),ability_id:Some(b::DRAW.into()),..Action::new("activate")});}else{break;}}assert!(activated);duplicate(t.value())}
#[test]fn jc053_native_natural_and_removal_export(){let cases=vec![natural(),prepared()];let mut binding=crate::bq052_tests::source_bindings();use sha2::{Digest,Sha256};for(n,bytes)in[("rust-game/src/jc053.rs",include_bytes!("jc053.rs").as_slice()),("rust-game/src/jc053_tests.rs",include_bytes!("jc053_tests.rs").as_slice())]{binding["files"][n]=serde_json::json!(format!("{:x}",Sha256::digest(bytes)));}if let Ok(p)=std::env::var("JC053_NATIVE_OUT"){std::fs::write(p,serde_json::to_vec(&serde_json::json!({"catalog":catalog::catalog(),"sourceBindings":binding,"cases":cases})).unwrap()).unwrap();}}
#[test]fn jc053_simultaneous_cancellation_records_both_teams(){let(mut g,_)=setup();enemy_removed(&mut g);assert_eq!(g.influence_removals.iter().map(|r|(r.team,r.amount)).collect::<Vec<_>>(),vec![(1,1),(0,1)]);restore(&mut g);}
#[test]fn jc053_activation_extra_payload_and_foreign_frame_rejected(){let(mut g,id)=setup();reject(&mut g,0,Action{card_id:Some(id.clone()),ability_id:Some(b::DRAW.into()),amount:Some(0),..Action::new("activate")});activate(&mut g,&id,b::DRAW);let mut x=g.clone();let f=x.stack.last_mut().unwrap().frame.as_mut().unwrap();f.steps=vec![Step{context:0,op:Op::Draw{player:PlayerRef::Actor,count:2,end:DeckEnd::Top}}];bad(&g,&x);let mut x=g.clone();let f=x.stack.last_mut().unwrap().frame.as_mut().unwrap();f.ability_key="foreign".into();f.steps.clear();bad(&g,&x);}
#[test]fn jc053_scored_region_clears_real_markers_into_current_history(){let(mut g,_)=setup();let uid=g.regions[0].card.id.clone();g.regions[0].influence[1]=1;g.effects.push_back(Effect::Score{seat:0,region:0});g.drive().unwrap();assert!(g.influence_removals.iter().any(|r|r.region_instance==uid&&r.team==1&&r.amount==1));restore(&mut g);}
